package it.financemanager.infrastructure.config;import it.financemanager.application.port.in.*;import it.financemanager.application.port.out.*;import it.financemanager.application.service.*;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.config.EnableJpaAuditing;import java.time.Clock;
@Configuration @EnableJpaAuditing public class ApplicationConfig{@Bean Clock clock(){return Clock.systemUTC();}@Bean AuthUseCase auth(UserPort u,PasswordPort p,TokenPort t){return new AuthService(u,p,t);}@Bean UserUseCase user(CurrentActorPort a,UserPort u){return new UserService(a,u);}@Bean CategoryUseCase category(CategoryPort c,CurrentActorPort a,UserPort u){return new CategoryService(c,a,u);}@Bean BudgetUseCase budget(BudgetPort b,CategoryPort c,CurrentActorPort a,UserPort u){return new BudgetService(b,c,a,u);}@Bean TransactionUseCase transaction(TransactionPort t,CategoryPort c,CurrentActorPort a,UserPort u){return new TransactionService(t,c,a,u);}@Bean DashboardUseCase dashboard(TransactionPort t,CurrentActorPort a,UserPort u,Clock c){return new DashboardService(t,a,u,c);}}
